// Format Maharashtra 7/12 record payload for Telegram & Sheets
const data = $input.first().json.body;
const doc = data.data || {};
const fields = doc.fields || {};

const survey = fields.survey_number ? fields.survey_number.value : (doc.survey_number || 'N/A');
const village = fields.village ? fields.village.value : (doc.village || 'N/A');
const taluka = fields.taluka ? fields.taluka.value : (doc.taluka || 'N/A');
const district = fields.district ? fields.district.value : (doc.district || 'Maharashtra');
const area = fields.total_area ? `${fields.total_area.value} ${fields.total_area.unit || 'Ha'}` : 'N/A';
const khatedar = fields.khatedar_names ? fields.khatedar_names.value : 'N/A';
const lrmsId = doc.external_lrms_id || doc.cadastral_code || 'PENDING_REGISTRY';
const officer = data.actor ? data.actor.email : 'System Officer';

const telegramMessage = `✅ *VERIBHOOMI 7/12 APPROVED & SYNCED*\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `🏛 *District:* ${district}\n` +
  `📍 *Taluka:* ${taluka} | *Village:* ${village}\n` +
  `📜 *Survey / Gat No:* ${survey}\n` +
  `👤 *Khatedar:* ${khatedar}\n` +
  `📐 *Area:* ${area}\n` +
  `🔗 *State LRMS ID:* \`${lrmsId}\`\n` +
  `✍️ *Approved by:* ${officer}\n` +
  `⏱ *Timestamp:* ${new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' })} IST`;

const emailSubject = `[VeriBhoomi Approval] 7/12 Record Approved: Gat ${survey} (${village}, ${taluka})`;
const emailHtml = `<h2>VeriBhoomi Land Records Modernization</h2>` +
  `<p>The following Maharashtra 7/12 record has been validated and synced with the State Cadastral Registry:</p>` +
  `<ul>` +
  `<li><b>Village / Taluka:</b> ${village}, ${taluka}, ${district}</li>` +
  `<li><b>Survey / Gat No:</b> ${survey}</li>` +
  `<li><b>Khatedar:</b> ${khatedar}</li>` +
  `<li><b>Total Area:</b> ${area}</li>` +
  `<li><b>LRMS External ID:</b> ${lrmsId}</li>` +
  `<li><b>Approving Officer:</b> ${officer}</li>` +
  `</ul>`;

return [{
  json: {
    timestamp: new Date().toISOString(),
    document_id: data.document_id,
    batch_id: data.batch_id,
    survey,
    village,
    taluka,
    district,
    area,
    khatedar,
    lrmsId,
    officer,
    telegramMessage,
    emailSubject,
    emailHtml
  }
}];

// Format rejection alert for operator telegram group
const data = $input.first().json.body;
const payload = data.data || {};
const officer = data.actor ? data.actor.email : 'Approving Officer';
const reason = payload.rejection_reason || 'Discrepancy in land area / owner names';
const filename = payload.filename || 'Scanned_712.pdf';

const telegramMessage = `⚠️ *VERIBHOOMI DOCUMENT REJECTED*\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `📄 *File:* ${filename}\n` +
  `🛑 *Rejection Reason:* ${reason}\n` +
  `👨‍💼 *Officer:* ${officer}\n` +
  `🆔 *Doc ID:* \`${data.document_id || 'N/A'}\`\n` +
  `⚡ *Action Required:* Please open Operator Queue to re-examine scan & resubmit.`;

return [{
  json: {
    document_id: data.document_id,
    filename,
    reason,
    officer,
    telegramMessage
  }
}];

// Format Redo Notice or Administrative Directive
const data = $input.first().json.body;
const payload = data.data || {};
const sender = data.actor ? `${data.actor.role.toUpperCase()} (${data.actor.email})` : 'Administrative Authority';
const title = payload.title || 'Administrative Directive';
const message = payload.message || 'Please inspect record fields.';
const notifType = payload.type || 'redo_request';

const telegramMessage = `🚨 *URGENT DIRECTIVE / REDO REQUEST*\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `📢 *Subject:* ${title}\n` +
  `📝 *Instructions:* ${message}\n` +
  `👤 *From:* ${sender}\n` +
  `🏷 *Priority:* ${notifType.toUpperCase()}\n` +
  `⏱ *Sent:* ${new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' })} IST`;

return [{
  json: {
    title,
    message,
    sender,
    notifType,
    telegramMessage
  }
}];

// Format Operator Revert notification for Officer
const data = $input.first().json.body;
const payload = data.data || {};
const operator = data.actor ? data.actor.email : 'Operator';
const title = payload.original_title || 'Redo Directive';
const reply = payload.reply_message || 'Correction applied.';

const telegramMessage = `🔄 *OPERATOR RESOLUTION / REVERT*\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `📌 *Regarding:* ${title}\n` +
  `💬 *Resolution Note:* ${reply}\n` +
  `👤 *Resolved by Operator:* ${operator}\n` +
  `✅ *Status:* Record is now ready for Tehsildar re-review.`;

return [{
  json: {
    title,
    reply,
    operator,
    telegramMessage
  }
}];
